  createCanvas(windowWidth, windowHeight,WEBGL);
  program = createShader(vert,frag);
}

function draw() {
  shader(program);
  // background(0);

	program.setUniform('u_resolution', [width*pixelDensity(), height*pixelDensity()]);
	program.setUniform('u_time', millis()/1000);
	program.setUniform('u_mouse', [map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),0,width,0,width*pixelDensity()), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),0,height,width*pixelDensity(),0)]);

  quad(-1, -1, 1, -1, 1, 1, -1, 1);
}


// === Tab: frag ===
var frag=`
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

float random (in vec2 _st) {
    return fract(sin(dot(_st.xy,
                         vec2(12.9898,78.233)))*
        43758.5453123);
}

// Based on Morgan McGuire @morgan3d
// https://www.shadertoy.com/view/4dS3Wd
float noise (in vec2 _st) {
    vec2 i = floor(_st);
    vec2 f = fract(_st);

    // Four corners in 2D of a tile
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}

#define NUM_OCTAVES 5

float fbm ( in vec2 _st) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    // Rotate to reduce axial bias
    mat2 rot = mat2(cos(0.5), sin(0.5),
                    -sin(0.5), cos(0.50));
    for (int i = 0; i < NUM_OCTAVES; ++i) {
        v += a * noise(_st);
        _st = rot * _st * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}

void main() {
    vec2 st = gl_FragCoord.xy/u_resolution.xy;
    st.x *= u_resolution.x/u_resolution.y;
    vec3 color = vec3(.0);
    float grid = 20.;

    // add vec2 offset & animate
    vec2 q = vec2(.0);
    q.x = fbm(st*10. + .3*u_time + u_mouse.x*.001);
    q.y = fbm(st*10. + .0*u_time + vec2(12., 55.) + u_mouse.y*.001);

    // add vec2 offset & animate
    vec2 r = vec2(.0);
    r.x = fbm(st*10. + q*4. + .0*u_time + vec2(896., 123.));
    r.y = fbm(st*10. + q*4. + .6*u_time + vec2(896., 123.));

    float f = fbm(st+r*4.);

    color = mix(vec3(0.0941, 0.0157, 0.0157), vec3(0.4863, 0.9412, 0.7059), clamp(f, 0., 1.));
    color = mix(color, vec3(0.8118, 0.5686, 0.0431), clamp(length(q.y), 0., 1.));
    color = mix(color, vec3(0.0196, 0.102, 0.1804), clamp(length(r.x), 0., 1.));

    gl_FragColor = vec4(1.-f*color,1.0);
}
`

